 22 | {
 23 |     // Compensate in reverse order.
 24 |     foreach (var step in Enumerable.Reverse(steps))
 25 |     {
 26 |         step.Compensate();
 27 |     }
 28 | }
 29 | 
 30 | Console.WriteLine($"Stock: {stock}, Balance: {balance}, Shipments: {shipments}");
 31 | 
